SELECT COUNT(*) FROM products p WHERE p.visible=1 AND EXISTS(SELECT 1 FROM variants av WHERE av.product_id=p.id AND av.price>0 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.size_unconfirmed')),'false') NOT IN ('true','1') AND ((av.availability='in' AND (JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.stock') IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.stock'))='null' OR CAST(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.stock')) AS DECIMAL(12,2))>0)) OR (av.availability='order' AND (TRIM(av.lead_time)<>'' OR (JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.availability_date')) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(av.data) THEN av.data ELSE '{}' END,'$.availability_date'))>=DATE_FORMAT(UTC_TIMESTAMP(),'%Y-%m-%d')))))) AND CASE WHEN LOWER(p.name) REGEXP '^(підсум|чохол|сумк|футляр|холдер|тримач)|рюкзак|баул|розвантаж|рпс|гідратор|бойовий пояс' THEN 'gear' WHEN LOWER(p.name) REGEXP 'аптеч|турнікет|джгут|гемостат|бандаж|ifak' THEN 'med' WHEN LOWER(p.name) REGEXP 'шкарпет|рукавич|рукавиц|наколін|налокіт' THEN 'small' WHEN LOWER(p.name) REGEXP 'шолом|каск|шапк|кепк|панам|бейсбол|балаклав|навушник|баф|окуляр' THEN 'head' WHEN LOWER(p.name) REGEXP 'берц|черевик|кросів|взутт|бахіл' THEN 'boots' WHEN LOWER(p.name) REGEXP 'плитоноск|бронежилет|бронеплит|бронепакет|балістичн.*пакет' THEN 'armor' WHEN LOWER(p.name) REGEXP 'штани|штанів|брюки|джогер|шорти' THEN 'legs' WHEN LOWER(p.name) REGEXP 'пояс|ремінь' THEN 'small' WHEN LOWER(p.name) REGEXP 'курт|убакс|ubacs|сороч|футбол|поло|термобілиз|термобель|фліс|флис|кофта|худі|софтшел|пончо|костюм' THEN 'body' WHEN LOWER(p.category_path) REGEXP 'медицин|медицина' THEN 'med' WHEN LOWER(p.category_path) REGEXP 'голов|шолом' THEN 'head' WHEN LOWER(p.category_path) REGEXP 'бронезахист' THEN 'armor' WHEN LOWER(p.category_path) REGEXP 'взуття' THEN 'boots' WHEN LOWER(p.category_path) REGEXP 'штани' THEN 'legs' WHEN LOWER(p.category_path) REGEXP 'рукавич|аксесуари одягу' THEN 'small' WHEN LOWER(p.category_path) REGEXP 'рюкзак|підсум|рпс|спорядження' THEN 'gear' WHEN LOWER(p.category_path) REGEXP 'одяг|форма' THEN 'body' ELSE 'small' END='med' AND EXISTS(SELECT 1 FROM photos sph WHERE sph.product_id=p.id) AND EXISTS(SELECT 1 FROM variants sv WHERE sv.product_id=p.id AND sv.price>0 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.size_unconfirmed')),'false') NOT IN ('true','1') AND ((sv.availability='in' AND (JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.stock') IS NULL OR JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.stock'))='null' OR CAST(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.stock')) AS DECIMAL(12,2))>0)) OR (sv.availability='order' AND (TRIM(sv.lead_time)<>'' OR (JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.availability_date')) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(sv.data) THEN sv.data ELSE '{}' END,'$.availability_date'))>=DATE_FORMAT(UTC_TIMESTAMP(),'%Y-%m-%d'))))));
